    on abuser_register (customer_id);

create table ace_send_voucher
(
    ace_send_voucher_id int auto_increment comment 'Primary key for ace_send_voucher'
        primary key,
    customer_id_sender  int          null comment 'Customer ID that send the voucher',
    email_receiver      varchar(128) null comment 'Email that will receive the voucher',
    voucher_code        varchar(255) null comment 'Voucher that being sent',
    voucher_type        smallint     null comment '1. Registration
2. Refund
3. General
4. Cashback
5. Redeem
6. New Retail -> exclude dari user blacklist
7. Digital Stamp
8. Voucher As Cash
9. Internas Sales GP',
    is_claim            tinyint      null comment '10 => voucher claimed by receiver
0 => voucher not claimed by receiver',
    created_at          datetime     null comment 'When the data is created',
    updated_at          datetime     null comment 'When the data is updated'
)
    engine = InnoDB;

create index customer_id_sender
    on ace_send_voucher (customer_id_sender);

create index email_receiver
    on ace_send_voucher (email_receiver);

