(
    credit_non_cc_transaction_id bigint auto_increment
        primary key,
    order_id                     varchar(50)                        not null,
    transaction_id               varchar(255)                       null,
    tenor                        int                                null,
    amount                       double                             not null,
    status                       varchar(10)                        null comment 'init/pending/expire/paid',
    action_url                   text                               null comment 'loan redirect url',
    loan_platform                varchar(30)                        null comment 'lender name such as kredivo, danakini, indodana, etc',
    transaction_date             datetime                           null,
    settlement_date              datetime                           null,
    cancel_reason                text                               null,
