create table customer
(
    customer_id             int auto_increment
        primary key,
    first_name              varchar(135) charset utf8mb3                   null,
    last_name               varchar(135)                default ''         null,
    email                   varchar(128) charset utf8mb3                   null,
    password                varchar(256) charset utf8mb3                   null,
    phone                   varchar(30) charset utf8mb3                    null,
    international_dial_code varchar(10)                                    null,
    birth_date              date                                           null,
    gender                  enum ('male', 'female') charset utf8mb3        null,
    status                  tinyint                     default 10         null comment 'customer black list => -2
customer deleted => -1
customer disabled=> 0
customer is guest => 5
customer enabled=> 10',
    ktp_no                  varchar(16)                                    null,
    is_new                  tinyint                     default 10         null comment '0 => Customer belum sama sekali melakukan order di RR
10 => Customer sudah melakukan order di RR

Purpose : Marketing Conditions',
    created_at              datetime                                       null,
    updated_at              datetime                                       null,
    last_login              datetime                                       null,
    password_token          varchar(45) charset utf8mb3                    null comment 'fields to save token for validation when user asked for reset password',
    registered_by           varchar(30) charset utf8mb3 default 'ruparupa' null,
    company_code            varchar(45)                 default 'ODI'      null,
    fingerprint             varchar(128)                                   null,
    is_phone_verified       tinyint                     default 0          not null,
    is_email_verified       tinyint                     default 0          not null,
    original_company_code   varchar(11)                                    null,
    login_attempt           tinyint                     default 0          null comment 'count of validate password attempt',
    login_attempt_time      datetime                                       null
)
    engine = InnoDB;

create table affiliate
(
    affiliate_id            int auto_increment
        primary key,
    customer_id             int            default 0                 not null,
    affiliate_group_id      int            default 0                 not null,
    first_name              varchar(255)                             null,
    last_name               varchar(255)                             null,
    phone_number            varchar(30)                              null,
    email                   varchar(125)                             null,
    balance                 decimal(10, 2) default 0.00              null,
    gender                  varchar(15)                              null comment 'Laki-laki, Perempuan',
    account_type            varchar(15)                              null comment 'individu, bisnis',
    registered_date         datetime                                 null,
    interests               varchar(255)                             null,
    social_media            text                                     null,
    province                varchar(100)                             null,
    city                    varchar(100)                             null,
    district                varchar(100)                             null,
    postal_code             varchar(10)                              null,
    address                 text                                     null,
    status                  varchar(100)                             null,
    approved_date           datetime                                 null,
    approved_by             varchar(255)                             null,
    nik                     varchar(100)                             null,
    npwp                    varchar(100)                             null,
    buku_tabungan           varchar(255)                             null,
    ktp_url                 varchar(255)                             null,
    npwp_url                varchar(255)                             null,
    additional_tnc          tinyint        default 0                 null,
    created_at              datetime       default CURRENT_TIMESTAMP not null,
    nik_updated_at          datetime                                 null,
    is_affiliated_elsewhere tinyint        default 0                 null,
    is_employee             tinyint        default 0                 not null,
    constraint customer_id_1_FK
        foreign key (customer_id) references customer (customer_id)
            on delete cascade
)
    engine = InnoDB;

create index email_affiliate_IDX
    on affiliate (email);

create index phone_number_affiliate_IDX
    on affiliate (phone_number);

