create table affiliate_fraud_case
(
    case_id                     int auto_increment comment 'Primary key for the fraud case'
        primary key,
    affiliate_id                int                                not null comment 'Reference to the affiliate involved in the case, linked to affiliate table',
    fraud_id                    int                                not null comment 'Reference to the type of fraud detected, linked to affiliate_fraud_master table',
    created_by                  varchar(255)                       null comment 'User or system that created the fraud case',
    fraud_note                  varchar(255)                       null comment 'Description or notes related to the fraud case',
    case_status                 varchar(31)                        not null comment 'Current status of the case (Pending, On Review, Cleared, Rejected, Replaced)',
    proof_kartu_keluarga_number varchar(255)                       null comment 'Number from the Kartu Keluarga (Family Card) used as proof',
    proof_kartu_keluarga_file   varchar(255)                       null comment 'File name or path for the Kartu Keluarga proof',
    proof_selfie_ktp_file       varchar(255)                       null comment 'File name or path for the Selfie KTP proof',
    proof_statement_letter_file text                               null comment 'Statement letter proof',
    proof_social_media_file     text                               null comment 'File name or path for the social media proof',
    proof_note                  varchar(255)                       null comment 'Additional notes or explanation about the provided proof',
    is_cleared                  tinyint                            not null comment 'Flag to indicate if the case has been cleared (0 = No, 10 = Yes)',
    reviewed_by                 varchar(255)                       null comment 'User who reviewed the fraud case',
    review_reason               varchar(255)                       null comment 'Reason provided during the review of the case',
    reviewed_at                 datetime                           null comment 'Date and time when the case was reviewed',
    unblocked_by                varchar(255)                       null comment 'User who unblocked the fraud case',
    unblock_reason              varchar(255)                       null comment 'Reason for unblocking the affiliate',
    unblocked_at                datetime                           null comment 'Timestamp when the affiliate was unblocked',
    created_at                  datetime default CURRENT_TIMESTAMP not null comment 'Timestamp when the fraud case was created',
    updated_at                  datetime default CURRENT_TIMESTAMP not null on update CURRENT_TIMESTAMP comment 'Timestamp when the fraud case was last updated',
    constraint fk_affiliate_fraud_case_affiliate_id
        foreign key (affiliate_id) references affiliate (affiliate_id),
    constraint fk_affiliate_fraud_case_fraud_id
        foreign key (fraud_id) references affiliate_fraud_master (fraud_id)
)
    engine = InnoDB;

