create table customer_b2b_account
(
    customer_b2b_account_id int auto_increment
        primary key,
    company_salesman_id     int                                 null,
    email                   varchar(128)                        null,
    sap_no                  varchar(135)                        null,
    ktp_no                  varchar(16)                         null,
    company_group           varchar(135)                        null,
    address                 text                                null,
    kecamatan_id            int                                 null,
    city_id                 int                                 null,
    province_id             int                                 null,
    country_id              int                                 null,
    post_code               int                                 null,
    phone                   varchar(30)                         null,
    home_phone              varchar(30)                         null,
    fax                     varchar(30)                         null,
    website                 varchar(135)                        null,
    pkp_no                  varchar(30)                         null,
    pkp_date                timestamp                           null,
    pkp_type                varchar(135)                        null,
    npwp_document           varchar(135)                        null,
    sppkp_document          varchar(135)                        null,
    status                  int       default 0                 null comment '3: Customer submit B2B data, not yet approved by admin B2B.
10: B2B data submitted to SAP, received SAP no., and approved by admin B2B.',
    is_b2b_approved         int       default 0                 null comment '10 = Has been approved before; 0 = Never been approved before',
    k2_status               text                                null comment 'status customer from k2',
    k2_customer_id          varchar(100)                        null comment 'customer_id from k2',
    k2_request_no           varchar(30)                         null comment 'request_no from K2 after update / create account',
    transportation_zone     varchar(30)                         null comment 'transportation zone value get from K2',
    incoterms               varchar(30)                         null comment 'incoterms value from K2',
    incoterms2              varchar(30)                         null comment 'incoterms2 value from K2',
    created_at              timestamp default CURRENT_TIMESTAMP null,
    updated_at              timestamp                           null on update CURRENT_TIMESTAMP
