        primary key,
    term_of_payment             smallint                            not null comment '0 (paid before delivery), 7, 14, 21, 30 days',
    top_regist_file             text                                null comment 'term of payment registration file name',
    group_statement_letter      text                                null,
    payment_scheme_letter       text                                null,
    reason                      text                                null,
    requested_by                int                                 not null comment 'customer id',
    processed_by                int                                 null comment 'admin_user.admin_user_id',
    status                      varchar(20)                         not null comment 'new and approved',
    created_at                  timestamp default CURRENT_TIMESTAMP null,
    updated_at                  timestamp                           null on update CURRENT_TIMESTAMP,
