        primary key,
    customer_b2b_account_id     int                                 not null,
    customer_b2b_top_request_id int                                 null,
    term_of_payment             smallint                            not null comment '0 (paid before delivery), 7, 14, 21, 30 days',
    top_regist_file             text                                null comment 'term of payment registration file name',
    group_statement_letter      text                                null,
