    reason                      text                                null,
    company_potencial           varchar(10)                         null comment 'company potencial value from K2',
    account_group               varchar(30)                         null comment 'credit limit filled by admin k2',
    credit_limit                decimal                             null comment 'credit limit filled by admin k2',
    company_code                varchar(4)                          not null comment 'Filled with AHI/HCI',
    created_at                  timestamp default CURRENT_TIMESTAMP null,
    updated_at                  timestamp                           null on update CURRENT_TIMESTAMP,
    constraint customer_b2b_term_of_payment_ibfk_1
        foreign key (customer_b2b_top_request_id) references customer_b2b_term_of_payment_request (customer_b2b_top_request_id)
            on update cascade on delete cascade,
    constraint customer_b2b_term_of_payment_ibfk_2
        foreign key (customer_b2b_account_id) references customer_b2b_account (customer_b2b_account_id)
