create table marketing_bulk_insert
(
    marketing_bulk_insert_id int unsigned auto_increment
        primary key,
    batch_name               varchar(100)                          not null,
    file_name                varchar(255)                          not null,
    file_description         varchar(255)                          not null,
    bulk_type                varchar(50)                           not null comment '-salesrule /n -salesrule_voucher',
    customer_group_id        varchar(20) default '0'               null,
    processed_date           datetime                              null,
    user_email               varchar(100)                          not null comment 'user admin created bulk data',
    status                   varchar(25)                           not null comment '-Pending /n -On progress /n -Done',
    tnc                      longtext                              not null,
    error_count              int         default 0                 null,
    overlapped_rules_count   int         default 0                 null,
    rule_id_generated        varchar(20)                           null comment 'rule_id stored after batch salesrule done run',
    download_file            varchar(255)                          null comment 'path to store logs after run batch',
    prefix_name              varchar(255)                          not null,
    schema_id                int                                   not null,
    salesrule_data           mediumtext                            not null,
    created_at               datetime    default CURRENT_TIMESTAMP null,
    updated_at               datetime    default CURRENT_TIMESTAMP not null on update CURRENT_TIMESTAMP,
    error_reason             text                                  null
)
