create table marketplace_acquisition_reward
(
    marketplace_acquisition_reward_id int auto_increment
        primary key,
    unify_master_merchant_id          int                                not null,
    reward_type                       varchar(31)                        not null comment 'Type of reward (voucher, coin)',
    discount_type                     varchar(31)                        not null comment 'Type of discount (fix, percent)',
    percentage                        int                                null comment 'Percentage of voucher or coin if discount_type = percent',
    max_coin                          decimal(12, 2)                     null comment 'Max redemption of coin',
    rule_id                           int unsigned                       null comment 'FK to salesrule table',
    voucher_amount                    decimal(12, 2)                     null comment 'Voucher discount amount',
    max_voucher_redemption            decimal(12, 2)                     null comment 'Max redemption of voucher if discount_type = percent',
    voucher_code_length               int                                null,
    voucher_code_prefix               varchar(255)                       null,
    voucher_expired_after_days        int                                null comment 'Number of days before the voucher expires after being generated',
    status                            tinyint                            not null comment 'Status (0 = inactive, 1 = active)',
    ms_link                           varchar(255)                       not null comment 'Vendor redirection link to Ruparupa',
    created_at                        datetime default CURRENT_TIMESTAMP not null,
    updated_at                        datetime default CURRENT_TIMESTAMP not null on update CURRENT_TIMESTAMP
)
    engine = InnoDB
    charset = utf8mb3;

