create table admin_user_attribute_value
(
    admin_user_attribute_value_id int unsigned auto_increment
        primary key,
    admin_user_id                 int unsigned not null,
    master_app_id                 int unsigned not null,
    admin_user_attribute_id       int unsigned not null,
    value                         text         null,
    constraint fk_admin_user_attribute_value_admin_user1
        foreign key (admin_user_id) references admin_user (admin_user_id)
            on update cascade on delete cascade,
    constraint fk_admin_user_attribute_value_master_app1
        foreign key (master_app_id) references master_app (master_app_id)
            on update cascade on delete cascade
)
    engine = InnoDB
    charset = utf8mb3;

