    company_summary_background_url      text                                null comment 'digital stamps promotional background summary per business unit url',
    company_banner_image_url            text                                null comment 'digital stamps promotional banner image url',
    asset_style_theme_color             varchar(7)                          null comment 'hexadecimal code for promo digital stamps color theme',
    asset_style_stamp_image_url         text                                null comment 'image url for translating digital stamps number collected by customer into the stamps',
    asset_style_stamp_milestone_on_url  text                                null comment 'image url for digital stamps exchange milestone ON',
    asset_style_stamp_milestone_off_url text                                null comment 'image url for digital stamps exchange milestone OFF',
    company_name                        varchar(255)                        null comment 'company name of the promotion',
    asset_style_text_color              varchar(7)                          null comment 'hexadecimal code for promo digital stamps text color theme',
    is_premium_member                   tinyint   default 0                 not null comment 'is a flag for only allowing member premium to be able to collect digital stamps',
    is_allow_minus_stamps               tinyint   default 0                 not null comment 'is a flag for digital stamps collection summary minus',
    is_allow_multiple_redeem            tinyint   default 0                 not null,
    tnc                                 text                                not null,
    created_at                          timestamp default CURRENT_TIMESTAMP not null,
    updated_at                          timestamp default CURRENT_TIMESTAMP not null on update CURRENT_TIMESTAMP
)
    engine = InnoDB;

create table customer_digital_stamps
(
    customer_digital_stamps_id   int auto_increment
        primary key,
    config_digital_stamps_id     int            default 0                 not null comment 'master config digital stamps relationship',
    customer_id                  int                                      not null comment 'customer table relationship',
    member_no                    varchar(15)                              null comment 'for "logging" customer member number when digital stamps transaction happened',
    transfer_no                  varchar(30)                              null comment 'field to save transfer code from batch or endpoint to transfer digital stamps of past period(s)',
    receipt_id                   varchar(20)                              null comment 'offline transaction identifier',
    order_no                     varchar(20)                              null comment 'online transaction identifier',
    voucher_code                 varchar(25)                              null comment 'voucher code generated either for redeem from stamps or exchanging voucher back to digital stamps',
    refund_no                    varchar(25)                              null comment 'refund number references',
    stamp_collected              int            default 0                 not null comment 'total digital stamps collected (plus) from a transaction',
    stamp_deducted               int            default 0                 not null comment 'total digital stamps deducted (minus) from a transaction',
    stamp_addition_prevent_minus int            default 0                 not null comment 'Total addition to prevent stamp minus when refund or SR',
    invoice_transaction_amount   decimal(12, 2) default 0.00              not null,
    voucher_as_cash_amount       decimal(12, 2) default 0.00              not null,
    shipping_amount              decimal(12, 2) default 0.00              not null,
    shipping_discount_amount     decimal(12, 2) default 0.00              not null,
    handling_fee_adjust          decimal(12, 2) default 0.00              not null,
    source                       enum ('offline', 'online')               not null comment 'digital stamps transaction source',
    company_code                 enum ('AHI', 'HCI', 'TGI', 'ODI')        not null comment 'digital stamps business unit configuration ownership',
    note                         text                                     null,
    created_at                   timestamp      default CURRENT_TIMESTAMP not null,
    updated_at                   timestamp      default CURRENT_TIMESTAMP not null on update CURRENT_TIMESTAMP,
    constraint customer_digital_stamps_fk_1
        foreign key (config_digital_stamps_id) references master_config_digital_stamps (config_digital_stamps_id)
            on update cascade on delete cascade,
    constraint customer_digital_stamps_fk_2
        foreign key (customer_id) references customer (customer_id)
            on update cascade on delete cascade
)
    engine = InnoDB;

create index customer_digital_stamps_fk_1_idx
    on customer_digital_stamps (config_digital_stamps_id);

create index idx_order_no
    on customer_digital_stamps (order_no);

create index idx_receipt_id
    on customer_digital_stamps (receipt_id);

create index idx_voucher_code
    on customer_digital_stamps (voucher_code);

