create table customer_address
(
    address_id           int auto_increment
        primary key,
    customer_id          int                                                    not null,
    country_id           int                                                    null,
    province_id          int                                                    null,
    city_id              int                                                    null,
    kecamatan_id         int                                                    null,
    kelurahan_id         int                                                    null,
    first_name           varchar(135) charset utf8mb3 default 'NULL'            null,
    last_name            varchar(135)                 default ''                null,
    phone                varchar(130) charset utf8mb3 default 'NULL'            null,
    address_name         varchar(255) charset utf8mb3                           null,
    full_address         longtext charset utf8mb3                               null,
    post_code            varchar(120) charset utf8mb3 default 'NULL'            null,
    address_type         enum ('shipping', 'billing') charset utf8mb3           null,
    status               tinyint                      default 10                null comment '10->active, -1->inactive',
    is_default           tinyint                      default 0                 null,
    geolocation          varchar(100)                                           null,
    is_geolocation_valid tinyint                                                null comment '10 -> valid, 0 -> invalid',
    created_at           datetime                     default CURRENT_TIMESTAMP null,
    updated_at           datetime                                               null on update CURRENT_TIMESTAMP,
    constraint fk_customer_address_customer1
        foreign key (customer_id) references customer (customer_id)
            on update cascade on delete cascade,
    constraint fk_customer_address_master_country1
        foreign key (country_id) references master_country (country_id)
            on update cascade on delete cascade,
    constraint fk_customer_address_master_kelurahan1
        foreign key (kelurahan_id) references master_kelurahan (kelurahan_id)
            on update cascade on delete cascade,
    constraint fk_customer_address_master_province1
        foreign key (province_id) references master_province (province_id)
            on update cascade on delete cascade
)
    engine = InnoDB;

