create table mission_master_event
(
    mission_master_event_id int auto_increment
        primary key,
    code                    varchar(255) null,
    name                    varchar(255) null,
    source                  varchar(20)  null comment 'be, fe, manual',
    condition_attributes    text         null,
    constraint mission_master_event_code_IDX
        unique (code)
)
    engine = InnoDB;

grant delete, insert, select, update on table mission_master_event to rahmatbst;

create table mission_master_reward
(
    mission_master_reward_id int auto_increment
        primary key,
    name                     varchar(255)            not null,
    type                     varchar(50)             null,
    fields                   text                    null,
    position                 tinyint      default 0  not null,
    status                   tinyint      default 0  not null comment '0 = Inactive, 10 = Active',
    banner_reward_url        varchar(255) default '' not null
)
    engine = InnoDB;

create table mission
(
    mission_id                  int auto_increment
        primary key,
    name                        varchar(255)                not null,
    description                 text                        null,
    mission_type                varchar(20)                 null comment 'general, affiliate',
    tnc                         text                        null,
    status                      tinyint                     not null comment '0 = Inactive, 10 = Active',
    start_date                  datetime                    not null,
    end_date                    datetime                    not null,
    time_before_inactive        varchar(10)                 null comment 'format: X,Y where X is an integer number, Y is one of H (hour), D (day), M (month)',
    enroll_per_customer         int            default 0    not null,
    enroll_per_customer_days    int            default 0    not null,
    sequence_flag               tinyint        default 0    null comment '0 = Not Sequential, 1 = Sequential',
    total_quota                 int            default 0    not null,
    total_achieved              int            default 0    not null,
    total_in_progress           int            default 0    not null,
    total_quota_remaining       int            default 0    not null,
    reward_id                   int                         null,
    reward_amount               decimal(10, 2) default 0.00 null,
    reward_amount_type          varchar(20)                 null comment 'fix, final_amount, percent',
    reward_max_redemption       decimal(10, 2) default 0.00 null,
    reward_rule_id              int                         null,
    reward_expired_after_days   int                         null,
    last_enroll_date            datetime                    not null,
    event_flag                  smallint       default 0    not null,
    banner_url                  varchar(255)   default ''   not null,
    banner_is_publish           smallint       default 0    not null,
    daily_checkin_sequence_flag smallint       default 0    not null,
    reward_code_length          int            default 10   null,
    reward_code_prefix          varchar(255)   default ''   null,
    constraint fk_reward_1
        foreign key (reward_id) references mission_master_reward (mission_master_reward_id)
            on update cascade
)
    engine = InnoDB;

create index end_date_INDEX
    on mission (end_date);

create index start_date_INDEX
    on mission (start_date);

grant delete, insert, select, update on table mission to rahmatbst;

create table mission_customer
(
    mission_customer_id int auto_increment
        primary key,
    mission_id          int      not null,
    customer_id         int      not null,
    enrolled_date       datetime not null,
    time_to_inactive    datetime not null,
    status              tinyint  not null,
    eliminated_date     datetime null,
    completed_date      datetime null,
    latest_event_date   datetime null,
    constraint mission_customer_FK
        foreign key (customer_id) references customer (customer_id),
    constraint mission_customer_FK_1
        foreign key (mission_id) references mission (mission_id)
)
    engine = InnoDB;

create index mission_customer_completed_date_IDX
    on mission_customer (completed_date);

create index mission_customer_eliminated_date_IDX
    on mission_customer (eliminated_date);

