create table product_category
(
    category_id               int unsigned auto_increment comment 'entity_id'
        primary key,
    parent_id                 int          default 0         null comment 'parent_id',
    attribute_set_id          int          default 184       null,
    attribute_variant_set_id  int          default 1         null,
    article_hierarchy         varchar(45)                    null,
    terminology               varchar(255)                   null,
    name                      varchar(255)                   null comment 'Name',
    title                     varchar(100) default ''        not null,
    meta_title                varchar(255)                   null comment 'Page Title',
    meta_keywords             text                           null comment 'Meta Keywords',
    meta_description          text                           null comment 'Meta Description',
    path                      varchar(255) default ''        null comment 'path',
    position                  int          default 0         null comment 'position',
    level                     int          default 0         null comment 'level',
    children_count            int          default 0         null comment 'children_count',
    header_description        longtext                       null,
    header_description_mobile longtext                       null,
    footer_description        longtext                       null comment 'Description',
    display_mode              varchar(255)                   null comment 'Display Mode',
    description               text                           null,
    icon                      varchar(255)                   null comment 'Icon',
    image                     varchar(255)                   null comment 'Image',
    url_path_image            text                           null,
    thumbnail                 varchar(255)                   null,
    thumbnail_mobile          varchar(255)                   null,
    mini_category_banner      varchar(255)                   null,
    show_thumbnail            tinyint      default 0         null,
    include_in_menu           int                            null comment 'Include in Navigation Menu',
    start_time                timestamp                      null,
    end_time                  timestamp                      null,
    show_on_app               tinyint      default 1         not null,
    is_anchor                 int                            null comment 'Is Anchor',
    page_layout               tinyint      default 0         null comment 'Page Layout',
    hexa_code                 varchar(45)  default '#FFFFFF' null,
    category_key              varchar(255)                   null comment 'URL Key',
    url_path                  varchar(255)                   null comment 'Url Path',
    best_seller               text                           null,
    status                    tinyint      default 10        null comment 'Is Active',
    is_rule_based             tinyint                        null,
    company_code              varchar(45)  default 'ODI'     null,
    filter_condition          text                           null,
    rule_based_hero_products  text                           null,
    vm_most_sales             int          default 0         not null,
    vm_most_click             int          default 0         not null,
    vm_add_to_cart            int          default 0         not null,
    vm_slow_moving            int          default 0         not null,
    vm_new_arrival            int          default 0         not null,
    vm_special_price          int          default 0         not null,
    exclude_category          text                           null,
    exclude_sku               text                           null,
    canonical_url             varchar(255)                   null comment 'Canonical URL',
    tags                      text                           null,
    index_setup               varchar(255)                   null comment 'No Index Set Up',
    created_at                timestamp                      null comment 'created_at',
    updated_at                timestamp                      null comment 'updated_at'
)
    engine = InnoDB
    charset = utf8mb3;

