create table product_stock_override_stock
(
    override_id   int auto_increment
        primary key,
    sku           varchar(50)                           not null,
    store_code    varchar(50)                           not null,
    qty_override  int                                   not null,
    start_date    datetime                              not null,
    end_date      datetime                              not null,
    type_override varchar(50) default 'onhand'          not null comment 'Ilustration override stock
================================
Type : onhand
    - override stock : 100
    - Type : onhand
    - store_code : A322
    - sku : X321233
    - [existing] on hold payment : 4
    - [existing] on hold shipment : 2
    - [existing] on hand : 15
    - [existing] on buffer : 3
    - [existing] available : 6 ( 15 - ( 4+2+3 ) )

    - [result] on hand : 100
    - [result] available : 91 ( 100 - ( 4+2+3 ) )

Type : available
    - override stock : 100
    - Type : available
    - store_code : A322
    - sku : X321233
    - [existing] on hold payment : 4
    - [existing] on hold shipment : 2
    - [existing] on hand : 15
    - [existing] on buffer : 3
    - [existing] available : 6 ( 15 - ( 4+2+3 ) )

    - [result] on hand : 109 ( 100 + ( 4+2+3 ) )
    - [result] available : 100 ',
    status        tinyint     default 10                not null,
    filename      varchar(255)                          not null,
    admin_user_id varchar(255)                          not null,
    created_at    datetime    default CURRENT_TIMESTAMP not null
)
    engine = InnoDB
    charset = utf8mb3;

create index idx_sku
    on product_stock_override_stock (sku);

create index idx_store_code
    on product_stock_override_stock (store_code);

