create table product_stock_request
(
    id             int auto_increment
        primary key,
    requester_nip  varchar(100)                         not null comment 'employee nip who ask to add product stock',
    requester_name varchar(255)                         not null comment 'employee name who ask to add product stock',
    sku            varchar(255)                         not null comment 'requested product stock sku',
    store_code     varchar(10)                          not null comment 'requested product stock store code',
    product_name   varchar(255)                         null,
    quantity       int                                  not null comment 'amount number of quantity that will be added',
    status         enum ('new', 'approved', 'rejected') not null comment 'new : default status for new request
approved : approved by approver and updated quantity on hand stock
rejected : rejected by approver',
    admin_user_id  int      default 0                   null comment 'stock request approver
- store manager
- CSO RR
- O admin',
    source         varchar(50)                          not null comment 'stock request app origin',
    approval_at    datetime                             null,
    created_at     datetime default CURRENT_TIMESTAMP   null,
    updated_at     datetime                             null on update CURRENT_TIMESTAMP
)
    engine = InnoDB
    collate = utf8mb4_general_ci;

create index product_stock_request_id_IDX
    on product_stock_request (id);

create index product_stock_request_requester_nip_IDX
