    name                     varchar(100)                         null,
    meta_title               varchar(100)                         null,
    meta_keyword             text                                 null,
    meta_description         text                                 null,
    package_content          text                                 null,
    warranty_code            varchar(30)                          null,
    warranty_unit            varchar(45)                          null,
    warranty_part            varchar(45)                          null,
    warranty_services        varchar(45)                          null,
    warranty_contributor     varchar(45) default 'no contributor' null comment '''supplier'',''ruparupa''',
    packaging_uom            varchar(5)  default 'CM'             null comment 'M, CM',
    packaging_height         decimal(10, 2)                       null,
    packaging_length         decimal(10, 2)                       null,
    packaging_width          decimal(10, 2)                       null,
    product_height           decimal(10, 2)                       null,
    product_width            decimal(10, 2)                       null,
    product_length           decimal(10, 2)                       null,
    weight                   decimal(10, 2)                       null,
    description              text                                 null,
    how_to_use               text                                 null,
    tips_trick               text                                 null,
    specification            text                                 null,
    video_link               varchar(255)                         null,
    url_key                  varchar(100)                         null,
    ownfleet_template_id     int                                  null comment 'MP Propose',
    wilayah_template_id      varchar(45)                          null,
    courier_id               varchar(45) default '1'              null comment 'MP Propose',
    shared_commision         decimal(10, 2)                       null comment 'MP Propose',
    increment_id             int                                  null comment 'MP Propose',
    default_sort             int         default 0                null,
    popularity               int         default 0                null,
    related_product          text                                 null,
    status                   tinyint     default 0                null comment '-1 => delete
0 => disabled
10 => enabled',
    created_at               datetime                             null,
    updated_at               datetime                             null
)
    engine = InnoDB
    charset = utf8mb3;

create table product_variant
(
    product_variant_id   int auto_increment
        primary key,
    product_id           int                             not null,
    sku                  varchar(30)                     null,
    sku_seller           varchar(100)                    null,
    is_in_stock          tinyint     default 1           null comment '0 => Out Of Stock
1 => In Stock',
    label                varchar(200)                    null,
    status               tinyint     default 0           null comment '-1 => deleted
0 => disabled
10 => enabled',
    status_buyer         varchar(30) default 'saleable'  null comment 'discontinued => takeout | no active
incoming products => not takeout | no active
temporary discontinued
part not saleable => takeout | active
saleable => not takeout | active',
    status_content       varchar(30) default 'new'       null comment '''new'',''pending check buyer bu'',''ready check buyer bu'',''ready recheck content'',''done pending'',''complete'',''temporary_hold_by_request''',
    status_image         varchar(30) default 'not exist' null comment '''not exist'',''complete''',
    remark_buyer_bu      text                            null,
    remark_content       text                            null,
    status_mp            varchar(30) default 'pending'   null comment '1. pending
2. locked
3. approved
4. rejected
5. deleted',
    status_buyer_mp      varchar(30) default 'pending'   null comment '- pending
- locked
- approved
- rejected',
    gtin                 varchar(100)                    null,
    ownfleet_template_id int                             null,
    publish_date         datetime                        null,
    priority             int         default 10000       null,
    created_at           datetime                        null,
    updated_at           datetime                        null,
    constraint sku_UNIQUE
        unique (sku),
    constraint fk_product_variant_product1
        foreign key (product_id) references product_x (product_id)
            on update cascade on delete cascade
)
    engine = InnoDB
    charset = utf8mb3;

create table product_images
(
    image_id           int auto_increment
        primary key,
    product_variant_id int                not null,
    image_tag          varchar(45)        null,
    image_info         text               null,
    image_url          varchar(255)       null,
    image_beta_url     varchar(255)       null,
    angle              tinyint default 1  null,
    status             tinyint default 10 null comment '-1 => delete
0 => disabled
10 => enabled',
    created_at         datetime           null,
    updated_at         datetime           null,
    constraint fk_product_images_product_variant1
        foreign key (product_variant_id) references product_variant (product_variant_id)
            on update cascade on delete cascade
)
    engine = InnoDB
    charset = utf8mb3;

