create table promo_pos_buys
(
    promo_pos_buy_id int auto_increment
        primary key,
    sap_promo_type   varchar(15)                         not null comment 'sap promo type code',
    member_flag      tinyint   default 0                 not null comment 'for flagging should we check field site_sap and MEMBER_FLAG for the promotion',
    stock_code       varchar(15)                         null,
    qty              int       default 0                 not null,
    promo_sap_id     varchar(20)                         null comment 'sap promotion number; except remark column equals "-TIMESERVICE-" promotion sap number would be empty',
    promo_sap_name   varchar(100)                        null comment 'sap promotion name',
    start_date       datetime                            null comment 'promotion start date',
    end_date         datetime                            null comment 'promotion end date',
    price_zone       int       default 0                 not null comment 'promotion price zone target',
    min_item_group_r int       default 0                 not null comment 'for buy 1 get 1 promotion, min_item_group is a term for how much item could be bought by customer (could be mixed article number)',
    min_item_group_m int       default 0                 not null comment 'for buy 1 get 1 promotion, min_item_group is a term for how much item could be bought by customer (could be mixed article number)',
    max_qty_disc_r   int       default 0                 not null comment 'maximum item allowed to get special price',
    max_qty_disc_m   int       default 0                 not null comment 'maximum item allowed to get special price',
    remarks          varchar(50)                         null comment 'remarks value',
    created_at       timestamp default CURRENT_TIMESTAMP not null,
    updated_at       timestamp default CURRENT_TIMESTAMP not null on update CURRENT_TIMESTAMP
)
    engine = InnoDB;

