create table promo_pos_headers
(
    promo_pos_header_id            int auto_increment
        primary key,
    site_sap                       varchar(5)                               null comment 'store code',
    sap_promo_type                 varchar(15)                              not null comment 'sap promo type code',
    member_flag                    tinyint        default 0                 not null comment 'for flagging should we check field site_sap and MEMBER_FLAG for the promotion',
    promo_sap_id                   varchar(15)                              not null comment 'sap promo type code',
    promo_sap_name                 varchar(100)                             null comment 'sap promotion name',
    start_date                     datetime                                 null comment 'promotion start date',
    end_date                       datetime                                 null comment 'promotion end date',
    price_zone                     int            default 0                 not null comment 'promotion price zone target',
    company_code                   varchar(5)                               null comment 'company code sap',
    total_amount_r                 decimal(12, 2) default 0.00              not null comment '(minimum purchase) R means all customer',
    total_amount_m                 decimal(12, 2) default 0.00              not null comment '(minimum purchase) M means member',
    total_all_items                int                                      null comment 'if value = 1 lookup for total sales, if value = 0 see grand amount already fulfill or not',
    total_amount_max_r             decimal(12, 2) default 0.00              not null comment 'maximum purchase to get promo (non member)',
    total_amount_max_m             decimal(12, 2) default 0.00              not null comment 'maximum purchase to get promo (member)',
    discount_amount_r              decimal(12, 2) default 0.00              not null comment 'discount amount (all customer)',
    discount_amount_m              decimal(12, 2) default 0.00              not null comment 'discount amount (member)',
    discount_pct_r                 int            default 0                 not null comment 'discount percentage (all customer)',
    discount_pct_m                 int            default 0                 not null comment 'discount percentage (member)',
    coupon_r                       int            default 0                 not null comment 'raffle coupon (purchase x get y coupon for all customer)',
    coupon_m                       int            default 0                 not null comment 'raffle coupon (purchase x get y coupon for member)',
    bank_flag                      int            default 0                 not null comment 'if use bank get double promo (related to raffle coupon)',
    factor_next_pct                int            default 0                 not null comment 'customer sudah dapat voucher cashback dr trx pertama. ketika mengunakan voucher untuk trx kedua maka ada min trx',
    expired_date                   datetime                                 null comment 'promotion expired date for cashback promo',
    voucher_amount_r               decimal(12, 2) default 0.00              not null,
    voucher_amount_m               decimal(12, 2) default 0.00              not null,
    min_item_group_r               int            default 0                 not null comment 'for buy 1 get 1 promotion, min_item_group is a term for how much item could be bought by customer (could be mixed article number)',
    min_item_group_m               int            default 0                 not null comment 'for buy 1 get 1 promotion, min_item_group is a term for how much item could be bought by customer (could be mixed article number)',
    max_qty_disc_r                 int            default 0                 not null comment 'maximum item allowed to get special price',
    max_qty_disc_m                 int            default 0                 not null comment 'maximum item allowed to get special price',
    discount_pct_extra_r           int            default 0                 not null comment 'in percent (all customer)',
    discount_pct_extra_m           int            default 0                 not null comment 'in percent (member)',
    only_by_dept                   tinyint        default 0                 not null comment 'Flag 0/1 promo for specific department',
    dept                           varchar(255)                             null,
    discount_layered_flag          int            default 0                 not null comment '1. Hitung syarat total minimum belanja yang sudah kena promo termasuk / tidak (buat tentuin berlaku utk barang normal saja / tidak)
 2. Untuk pengenaan Discount, untuk barang dgn harga normal / barang yg kena promo"',
    multiply_flag                  int            default 0                 not null comment 'bisa berlaku kelipatan, contoh: beli 1 dpt 1, klo berlaku kelipatan berarti beli 2 dpt 2',
    point                          decimal(12, 2) default 0.00              not null,
    gift_to_lowest_price           int            default 0                 not null comment 'untuk promo buy 1 get 1, dia pilih harga yang paling murah',
    remarks                        varchar(50)                              null comment 'remarks value',
    receipt_messages               text                                     null comment 'receipt message shown in promotional voucher (like terms and conditions)',
    code                           varchar(50)                              null,
    payment_type                   varchar(255)                             null comment 'promo yang berlaku hanya utk pembayaran bank tertentu klo cashback berlaku utk bank tertentu, isi kode bin kartu credit',
    is_process                     tinyint        default 0                 not null comment 'is a flag for ourselve to mark this field already processed into salesrule',
    process_time                   datetime                                 null comment 'the date time mark of information when the data processed into salesrule',
    business_unit_name_from_folder varchar(20)                              null comment 'business unit name from processed folder',
    created_at                     timestamp      default CURRENT_TIMESTAMP not null,
    updated_at                     timestamp      default CURRENT_TIMESTAMP not null on update CURRENT_TIMESTAMP
)
    engine = InnoDB;

