create table retref_transfer_history
(
    id                         int auto_increment comment 'Primary key for retref_transfer_history'
        primary key,
    voucher_id_list            varchar(255)                null comment 'List of voucher id that is transferred',
    refund_no_list             varchar(255)                null comment 'List of refund no that is transferred',
    beneficiary_bank_code      varchar(50)                 null comment 'Destination bank code',
    beneficiary_bank_name      varchar(255)                null comment 'Destination bank name',
    beneficiary_account_number varchar(100)                null comment 'Destination bank account number',
    beneficiary_name           varchar(150)                null comment 'Destination bank account name',
    amount                     decimal(12, 2) default 0.00 null comment 'Amount transferred',
    transfer_method            varchar(45)                 null comment 'Transfer method used (bi_fast/switcher)',
    payload                    text                        null comment 'Transfer payload',
    response                   text                        null comment 'Transfer response',
    transfered_at              datetime                    null comment 'Transfer date',
    transfer_status            varchar(25)                 null comment 'Transfer status (success/failed)'
)
    engine = InnoDB;

create table retref_transfer_history_detail
(
    id              int auto_increment comment 'Primary key for retref_transfer_history_detail'
        primary key,
    rth_id          int           not null comment 'Refers to retref_transfer_history.id',
    voucher_id      int default 0 null comment 'Voucher id that is transferred',
    transfer_status varchar(25)   null comment 'Transfer status (success/failed)'
)
    engine = InnoDB;

create index retref_transfer_history_detail_rth_id_IDX
    on retref_transfer_history_detail (rth_id);

create index retref_transfer_history_detail_voucher_id_IDX
    on retref_transfer_history_detail (voucher_id);

create table retref_transfer_queue
(
    voucher_id                 int                          not null
        primary key,
    refund_no                  varchar(25) charset utf8mb3  not null,
    order_no                   varchar(25) charset utf8mb3  not null,
    origin_order_no            varchar(25) charset utf8mb3  not null,
    beneficiary_account_number varchar(100) charset utf8mb3 not null,
    beneficiary_bank_code      varchar(50) charset utf8mb3  not null,
    beneficiary_name           varchar(150) charset utf8mb3 not null,
    transfer_method            varchar(45)                  null comment 'Default value obtained from master_bca_bank_partner.transfer_method',
    transaction_id             varchar(64)                  null,
    external_id                varchar(64)                  null,
    reference_id               varchar(64)                  null,
    amount                     decimal(12, 2)               not null,
    amount_transfered          decimal(12, 2)               null,
    voucher_code               varchar(150) charset utf8mb3 not null,
    is_recheck                 int     default 0            not null,
    is_transfered              int     default 0            not null,
    status                     tinyint default 10           null comment '0 => inactive
6 => on process transfer
7 => is queueing for retry
10 => active and will be queued for transfer if is_recheck and is_transfered is false',
    user_id                    int                          not null,
    user_type                  varchar(10) charset utf8mb3  not null,
    created_at                 datetime                     null,
    transfered_at              datetime                     null,
    response                   text charset utf8mb3         null,
    note                       text charset utf8mb3         null,
    process_id                 varchar(100)                 null
)
    engine = InnoDB;

create index idx_beneficiary_account_number
    on retref_transfer_queue (beneficiary_account_number);

