create table sales_order
(
    sales_order_id           int unsigned auto_increment
        primary key,
    customer_id              int                              null,
    cart_id                  varchar(60)                      null,
    cart_type                varchar(200)                     null,
    status                   varchar(20)    default 'pending' null comment 'pending
processing
completed
canceled
refunded',
    device                   varchar(15)                      null comment 'device :
- empty = reorder
- android = RR Apps Android / Store Mode Android
- ios = RR Apps iOS / Store Mode iOS
- ace-android = Miss ACE android
- ace-ios = Miss ACE iOS
- mobile = mobile web
- Mozilla/5.0 (An = mobile web
- Mozilla/5.0 (iP = mobile web
- Mozilla/5.0 (Li = mobile web
- vendor = Shopee / Tokopedia',
    remote_ip                varchar(255)                     null,
    order_no                 varchar(50)                      not null,
    source_order_no          varchar(45)                      null comment 'Reference Order Number on Vendor ( Shopee and Tokopedia )',
    reference_order_no       varchar(50)                      null,
    parent_order_no          varchar(50)                      null,
    subtotal                 decimal(12, 2)                   null,
    discount_amount          decimal(12, 2)                   null,
    shipping_amount          decimal(12, 2)                   null,
    shipping_discount_amount decimal(12, 2)                   null,
    cart_rules               longtext                         null,
    gift_cards               text                             null,
    gift_cards_amount        decimal(12, 2)                   null,
    grand_total              decimal(12, 2)                   null,
    customer_note            text                             null,
    split_cost               text                             null,
    order_type               varchar(15)                      null,
    company_id               varchar(255)                     null,
    store_code               varchar(45)                      null,
    store_code_new_retail    varchar(25)                      null,
    company_code             varchar(45)    default 'ODI'     null,
    created_at               datetime                         null,
    updated_at               datetime                         null,
    has_changed_payment      int                              null comment '-1 = tidak bisa merubah pembayaran
0  = belum melakukan perubahan pembayaran
1 =  1x melakukan perubahan pembayaran
2 =  2x melakukan perubahan pembayaran',
    rrr_id                   varchar(30)                      null,
    mdr_customer             decimal                          null,
    marketing_version        varchar(10)                      null,
    insurance_amount         decimal(12, 2) default 0.00      not null
)
    engine = InnoDB
    charset = utf8mb3;

create table sales_invoice
(
    invoice_id                    int unsigned auto_increment comment 'Sales Invoice Id'
        primary key,
    invoice_status                varchar(50)                  null comment 'processing,
complete
,canceled
,refunded',
    sales_order_id                int unsigned                 not null,
    company_code                  varchar(45)    default 'ODI' null,
    subtotal                      decimal(12, 2)               null comment 'Subtotal Incl Tax
Formula :
( sales_invoice_item.selling_price + sales_invoice_item.handling_fee ) * sales_invoice_item.qty_ordered',
    discount_amount               decimal(12, 2)               null comment 'Discount Amount',
    shipping_amount               decimal(12, 2)               null comment 'Shipping Amount',
    shipping_discount_amount      decimal(12, 2)               null,
    handling_fee_adjust           decimal(12, 2)               null comment 'Formula :
price_zone.price - final_price ',
    grand_total                   decimal(12, 2)               null comment 'Formula :
(sales_invoice.subtotal - sales_invoice.discount_amount) + (sales_invoice.shipping_amount - sales_invoice.shipping_discount_amount) - sales_invoice.gift_cards_amount',
    qty_ordered                   decimal                      null comment 'Total Qty',
    invoice_no                    varchar(50)                  null comment 'Invoice Number',
    gift_cards_amount             decimal(12, 2)               null comment 'Gift Cards Amount',
    sap_so_number                 varchar(255)                 null,
    pickup_voucher                varchar(50)                  null comment 'Formula : sales_invoice.subtotal - sales_invoice.discount_amount
Voucher POS, sebagai alat pembayaran di Kasir.',
    delivery_method               varchar(25)                  null,
    store_code                    varchar(25)                  null,
    supplier_alias                varchar(50)                  null comment 'Company dari Store.
Relasi : store.supplier_id = supplier.supplier_id',
    pickup_code                   varchar(50)                  null,
    receipt_id                    varchar(255)                 null,
    real_price                    decimal(12, 2)               null comment 'Formula :
1. Event Insert from automata : sales_invoice.subtotal
2. Event Update from storedashboard : from POS / Input manual dari CS',
    pin_pos                       varchar(25)                  null,
    total_koli                    int                          null,
    status_packed                 tinyint                      null,
    sla_age                       int                          null,
    ttpu_no                       varchar(30)                  null,
    status_fulfillment            varchar(45)                  null comment 'lengkap,tidak_lengkap,batal',
    customer_pin_code             varchar(35)                  null comment 'maks 6 digit',
    created_at                    datetime                     null comment 'Created At',
    updated_at                    datetime                     null comment 'Updated At',
    status_so                     varchar(45)    default ''    null,
    receipt_id_fulfillment        varchar(255)                 null,
    insurance_amount              decimal(12, 2) default 0.00  not null,
    sales_invoice_process_type_id int                          null,
    constraint fk_sales_invoice_sales_order1
        foreign key (sales_order_id) references sales_order (sales_order_id)
)
    engine = InnoDB
    charset = utf8mb3;

