create table sales_order_payment
(
    payment_id            int auto_increment
        primary key,
    sales_order_id        int unsigned                            not null,
    method                varchar(45)                             null comment 'free_payment
gopay
niceva
ovo
shopee
tokopedia
vpayment => midtrans, type : credit_card not installment
vpaymentins => midtrans, type : credit_card installment, cc_type : bank, installment_tenor > 0
vpaymentva => midtrans, type : bank_transfer, va_bank : bank',
    type                  varchar(45)                             null comment 'bank_transfer
credit_card
debit_card
e_money
vendor',
    total_amount_ordered  double(15, 2) default 0.00              null,
    total_amount_paid     double(15, 2) default 0.00              null,
    total_amount_refunded double(15, 2) default 0.00              null,
    cc_type               varchar(45)                             null comment 'bca
bni
bri
mandiri',
    cc_number             varchar(45)                             null,
    cc_owner              varchar(255)                            null,
    installment_bank      varchar(45)                             null,
    installment_tenor     varchar(45)                             null,
    va_bank               varchar(45)                             null comment 'bca => vpaymentva
bii => niceva
BNI => niceva
bri => niceva
cimb => niceva
danamon => niceva
keb_hana => niceva
mandiri => niceva
permata => vpaymentva',
    va_number             varchar(45)                             null,
    bank_name             varchar(135)                            null,
    account_name          varchar(255)                            null,
    account_number        varchar(135)                            null,
    proof_of_payment      varchar(255)                            null,
    additional_data       text                                    null,
    expire_transaction    datetime                                null,
    status                varchar(20)   default 'pending payment' null comment 'pending payment
pending timeout
paid
refunded
frauded
',
    pg_transaction_id     text                                    null comment 'Record of current transaction id from payment gateway, if payment method changed then the value will be replaced with new transaction id',
    action_url            text                                    null comment 'Record of action url like qr url qris, redirect url gopay etc',
    acquirer              varchar(100)                            null comment 'bank or financial institution that processes customer credit or debit card payments',
    issuer                varchar(100)                            null comment 'bank or financial institution that issues payment cards, such as credit cards or debit cards',
    created_at            datetime                                null,
    updated_at            datetime                                null,
    can_cancel            int                                     null comment '0 = tidak bisa melakukan cancel 10 = bisa melakukan cancel',
    mark_as_paid_by       int                                     null comment 'identifier who marks as paid the transaction',
