create table sales_pending_order
(
    pending_order_id               int auto_increment
        primary key,
    parent_order_no                varchar(50)                              null comment 'Parent order no/first order that contain all item that customer bought',
    cart_id                        varchar(60)                              not null comment 'Cart id of first order/parent cart id that contain all item that customer bought',
    customer_id                    int                                      not null comment 'Customer''s id that own this pending order',
    pending_order_no               varchar(15)                              not null,
    items_grand_total              float                                    not null comment 'Grand total of all item on parent order that customer bought (item selling price * qty ordered)',
    shipping_amount                float       default 0                    not null comment 'Shipping amount from cart parent',
    additional_shipping_amount     float       default 0                    not null comment 'Additional shipping amount if admin wants to charge additional shipping amount to customer',
    handling_fee_adjust            float       default 0                    not null comment 'Handling fee adjust from cart parent',
    installation_amount            float       default 0                    not null comment 'Installation amount from cart parent (if customer request installation)',
    additional_installation_amount float       default 0                    not null comment 'Additional installation amount if admin wants to charge additional installation amount to customer',
    shipping_discount_amount       float       default 0                    not null comment 'Shipping discount amount from cart parent',
    discount_amount                float       default 0                    not null comment 'Discount amount from cart parent',
    gift_cards_amount              float       default 0                    not null comment 'Gift cards amount from cart parent',
    nearest_store_code             varchar(10)                              not null comment 'Nearest store code from customer shipping address. Retrieved from cart parent',
    status                         varchar(20) default 'waiting_validation' not null comment '- waiting_validation: Pending order need to be validated by admin (Admin must input shipping amount or installation amount)
- ready_to_checkout: Pending order has been validated by admin and waiting to be checked out by customer
- waiting_payment: Pending order has been create parent order, but not paid yet
- processing: Pending order has been paid and on process
- completed: Pending order has been completed
- canceled: Pending order has been canceled',
    validated_at                   datetime                                 null comment 'Date of admin has input shipping amount or installation amount if pending order needs to be validated (has waiting_validation status)',
    canceled_at                    timestamp                                null comment 'Date of pending order cancellation',
    created_at                     timestamp   default CURRENT_TIMESTAMP    not null,
    updated_at                     timestamp                                null on update CURRENT_TIMESTAMP,
    type                           varchar(20)                              not null,
    expired_at                     timestamp                                null,
    is_has_promo                   tinyint(1)                               null,
    proof_payment_uploaded_at      timestamp                                null
)
    engine = InnoDB;

create index sales_pending_order_cart_id_IDX
    on sales_pending_order (cart_id);

create index sales_pending_order_customer_id_IDX
    on sales_pending_order (customer_id);

create index sales_pending_order_parent_order_no_IDX
    on sales_pending_order (parent_order_no);

