- sales_order_id: Column sales_order_id from sales_order table
- sales_installation_id: Column sales_installation_id from sales_installation table',
    reference_key_value     int                                 not null comment 'Foreign key value of reference_key',
    status                  varchar(20)                         null comment '- waiting_validation: Pending order need to be validated by admin (Admin must input shipping amount or installation amount)
- ready_to_checkout: Pending order has been validated by admin and waiting to be checked out by customer
- waiting_payment: Pending order has been create parent order, but not paid yet
- processing: Pending order has been paid and on process
- completed: Pending order has been completed
- canceled: Pending order has been canceled',
    created_at              timestamp default CURRENT_TIMESTAMP not null,
    updated_at              timestamp                           null on update CURRENT_TIMESTAMP,
    constraint fk_sales_pending_order_detail_pending_order_id
        foreign key (pending_order_id) references sales_pending_order (pending_order_id)
            on update cascade on delete cascade
)
    engine = InnoDB;

