    cart_id                     varchar(64)                                                                                                                           null,
    order_no                    varchar(50)                                                                                                 default ''                not null comment 'related to `sales_order` table',
    po_no                       varchar(50)                                                                                                 default ''                not null,
    status                      enum ('draft', 'submitted', 'requested_proforma_invoice', 'proforma_invoice_sent', 'canceled', 'completed') default 'draft'           not null,
    draft_label_id              bigint                                                                                                                                null comment 'related to `master_quotation_wholesale_draft_label` table',
    reason                      varchar(256)                                                                                                default ''                not null,
    creation_source             varchar(32)                                                                                                                           null,
    attachment_file             varchar(256)                                                                                                                          not null,
    note                        text                                                                                                                                  null,
    company_code                varchar(8)                                                                                                  default 'ODI'             not null,
    is_invoice                  tinyint(1)                                                                                                  default 0                 not null,
    is_installation             tinyint(1)                                                                                                  default 0                 not null,
    is_not_use_promo            tinyint(1)                                                                                                  default 0                 not null,
    is_draft_final              tinyint(1)                                                                                                  default 0                 not null,
    is_stock_hold_payment       tinyint(1)                                                                                                  default 0                 not null,
    subtotal                    decimal(16, 2)                                                                                              default 0.00              not null,
    discount_amount             decimal(16, 2)                                                                                              default 0.00              not null,
    marketing_discount_amount   decimal(16, 2)                                                                                              default 0.00              not null,
    marketing_gift_cards_amount decimal(16, 2)                                                                                              default 0.00              not null,
    shipping_fee                decimal(16, 2)                                                                                              default 0.00              not null,
    shipping_fee_discount       decimal(16, 2)                                                                                              default 0.00              not null,
    discount_subtotal           decimal(16, 2)                                                                                              default 0.00              not null,
    created_at                  timestamp                                                                                                   default CURRENT_TIMESTAMP not null,
    updated_at                  timestamp                                                                                                   default CURRENT_TIMESTAMP not null on update CURRENT_TIMESTAMP,
    request_proforma_invoice_at timestamp                                                                                                                             null,
    proforma_invoice_at         timestamp                                                                                                                             null,
    customer_approved_draft_at  timestamp                                                                                                                             null,
    expired_at                  timestamp                                                                                                                             null,
    negotiation_at              timestamp                                                                                                                             null,
    constraint cart_id_idx
        unique (cart_id),
    constraint quotation_no
        unique (quotation_no),
    constraint fk_quotation_wholesale_label_draft
        foreign key (draft_label_id) references master_quotation_wholesale_draft_label (id),
    constraint fk_sales_quotation_wholesale_admin_user
        foreign key (created_by_admin_user_id) references admin_user (admin_user_id),
    constraint sales_quotation_wholesale_ibfk_1
        foreign key (customer_wholesale_id) references customer_wholesale (id)
)
    engine = InnoDB;

