create table sales_retref_dc
(
    retref_no               varchar(30)                                                                                                                                                                                                                  not null
        primary key,
    order_no                varchar(30)                                                                                                                                                                                                                  null,
    origin_order_no         varchar(30)                                                                                                                                                                                                                  null,
    invoice_no              varchar(30)                                                                                                                                                                                                                  null,
    invoice_id              int            default 0                                                                                                                                                                                                     null,
    subtotal                decimal(12, 2)                                                                                                                                                                                                               not null,
    refund_shipping_amount  decimal(12, 2)                                                                                                                                                                                                               not null,
    mdr_amount              decimal(12, 2) default 0.00                                                                                                                                                                                                  null,
    refund_shipping_default decimal(12, 2)                                                                                                                                                                                                               not null,
    insurance_amount        decimal(12, 2) default 0.00                                                                                                                                                                                                  null comment 'amount of refund for insurance item',
    customer_penalty        decimal(12, 2) default 0.00                                                                                                                                                                                                  null comment 'Amount voucher product deducted because insufficient coin balance',
    coin_deducted           decimal(12, 2) default 0.00                                                                                                                                                                                                  null comment 'Amount of coin deducted',
    send_email_claim_3pl    tinyint(1)                                                                                                                                                                                                                   null,
    reference_tugu_no       varchar(25)                                                                                                                                                                                                                  null,
    status                  enum ('new', 'approved', 'ship_from_customer', 'in_transit', 'dc_received', 'waiting_finance_billing', 'waiting_for_generate', 'generated', 'recheck', 'waiting_for_rekening', 'waiting_finance_ar', 'refunded', 'rejected') null,
    type                    enum ('refund', 'return')                                                                                                                                                                                                    null,
    criteria_id             tinyint                                                                                                                                                                                                                      null,
    admin_user_id           int unsigned                                                                                                                                                                                                                 null,
    handled_date            datetime                                                                                                                                                                                                                     null,
    generated_date          datetime                                                                                                                                                                                                                     null,
    arrival_date            datetime                                                                                                                                                                                                                     null,
    cso_note                mediumtext                                                                                                                                                                                                                   null,
    created_at              datetime       default CURRENT_TIMESTAMP                                                                                                                                                                                     not null,
    updated_at              datetime                                                                                                                                                                                                                     null
)
    engine = InnoDB
    collate = utf8mb4_general_ci;

