create table sales_return_refund
(
    refund_no                           varchar(25)                 not null comment 'Format :
RFyyyymmddxxxxxx
RTyyyymmddxxxxxx'
        primary key,
    status                              varchar(25)                 null,
    cso_note                            text                        null,
    order_no                            varchar(25)                 null,
    origin_order_no                     varchar(25)                 null,
    invoice_no                          varchar(25)                 null,
    reference_refund_no                 varchar(50)                 null,
    parent_refund_no                    varchar(50)                 null,
    group_refund                        smallint unsigned           null,
    subtotal                            decimal(12, 2)              null comment 'subtotal = selling_price + handling_fee_adjust',
    refund_shipping                     decimal(12, 2)              null,
    refund_shipping_default             decimal(12, 2)              null,
    insurance_amount                    decimal(12, 2) default 0.00 null comment 'amount of refund for insurance item',
    voucher_product_id                  int                         null comment 'voucher id, yang isi nya voucher pengganti product / barang',
    registration_voucher_amount         decimal(12, 2)              null,
    registration_voucher_amount_prorate decimal(12, 2)              null,
    voucher_registration_id             int                         null comment 'voucher id, yang isi nya voucher pengganti voucher registration ',
    redeem_voucher_amount               decimal(12, 2)              null,
    voucher_redeem_id                   int                         null comment 'voucher id, yang isi nya voucher pengganti voucher redeem point',
    paypoint_voucher_amount             decimal(12, 2)              null,
    voucher_paypoint_id                 int                         null comment 'voucher id, yang isi nya voucher pengganti voucher pay withpoint ga bisa cair ( rule_id 13765 )',
    refund_voucher_amount               decimal(12, 2)              null comment 'voucher product (VRTC) / credit memo yg direfund',
    voucher_refund_id                   int                         null comment 'voucher id, yang isi nya voucher pengganti voucher refund ga bisa cair ( rule_id 25, 48 )',
    refund_voucher_bc_amount            decimal(12, 2)              null comment 'pemakaian voucher product yang bisa dicairkan prefix VRDC',
    voucher_refund_bc_id                int                         null comment 'voucher id, yang isi nya voucher pengganti  voucher refund bisa cair ( rule_id 47 )',
    giftcard_voucher_amount             decimal(12, 2)              null comment 'all giftcards minus registration voucher',
    voucher_cashback_amount             decimal(12, 2)              null,
