create table sales_shipment
(
    shipment_id            int unsigned auto_increment comment 'Shipment Id'
        primary key,
    invoice_id             int unsigned         null,
    shipping_address_id    int unsigned         null,
    carrier_id             int                  null comment 'Carrier Code',
    shipment_status        varchar(50)          null,
    total_weight           decimal(10, 2)       null comment 'Total Weight (kg)',
    real_shipping_amount   decimal(12, 2)       null,
    shipped_date           datetime             null comment 'Shipped Date (with time)',
    delivered_date         datetime             null comment 'Delivered Date (with time)',
    track_number           varchar(150)         null comment 'Track Number / AWB Number',
    shipment_type          varchar(45)          null,
    insert_to_3pl          varchar(255)         null comment 'JNE, JNE JOB (because their server not stable)

exclude marketplace',
    pod_image              varchar(100)         null,
    do_image               varchar(100)         null,
    group_shipment         tinyint              null,
    express_courier_state  tinyint    default 0 null comment '0(unbook),5(cancel),10(booked)',
    eta                    varchar(100)         null,
    created_at             datetime             null comment 'Created At',
    updated_at             datetime             null comment 'Updated At',
    insurance_fee          decimal(12, 2)       null,
    must_use_insurance     tinyint(1) default 0 not null,
    insurance_applied      tinyint(1) default 0 not null,
    lead_time_min          int                  null,
    lead_time_max          int                  null,
    lead_time_unit         varchar(100)         null,
    initial_lead_time_min  int                  null,
    initial_lead_time_max  int                  null,
    initial_lead_time_unit varchar(25)          null,
    constraint fk_sales_shipment_sales_invoice1
        foreign key (invoice_id) references sales_invoice (invoice_id)
)
    comment 'Sales Shipment' engine = InnoDB
                             charset = utf8mb3;

