    name                              varchar(255)                                null comment 'Name',
    conditions                        text                                        null,
    description                       text                                        null comment 'Description',
    from_date                         datetime                                    null,
    to_date                           datetime                                    null,
    schedule                          varchar(255)      default ''                not null,
    use_voucher                       smallint unsigned default '0'               null comment '0 => No
1 => Yes',
    label_id                          int unsigned      default '0'               null comment 'mapping with product_labels',
    uses_per_customer                 int               default 0                 null comment '1 CUSTOMER boleh memakai voucher X kali',
    uses_per_customer_version         tinyint           default 0                 not null comment 'Version of uses per customer (0 = old version, 1 = new version)',
    uses_per_customer_option          varchar(50)                                 null comment 'Option selected (lifetime | unlimited | daily | weekly | monthly | custom)',
    uses_per_customer_from_date       smallint                                    null comment 'The initial date the promo can be used',
    uses_per_customer_to_date         smallint                                    null comment 'The end date the promo can be used',
    uses_per_customer_frequence       int               default 0                 null,
    total_purchase                    decimal(13)       default 0                 null,
    purchase_days                     int               default 0                 null,
    stop_rules_processing             smallint          default 0                 null comment 'Stop Rules Processing',
    can_refund                        tinyint           default 0                 not null,
    global_can_combine                tinyint           default 0                 null,
    qty_can_combine                   int               default 0                 not null comment 'a field to determine how much voucher with global can combine yes can be combined with its own rule, for example: `voucher digital stamps can only combine when sku in cart qty exactly same with voucher use quantity in single transaction`',
    can_combine                       tinyint           default 0                 null,
    priority                          int               default 0                 null comment 'Sort Order',
    landing_page_name                 varchar(255)                                null,
    landing_page_link                 text                                        null,
    bank_name                         varchar(50)                                 null,
    discount_type                     varchar(20)       default 'percent'         null comment '- percent
- fix',
    attributes                        varchar(100)                                null comment 'shipping_fee, product, grand_total, subtotal, items X',
    discount_amount                   decimal(12, 2)    default 0.00              null comment 'Percent / Fix Off',
    split_budget                      tinyint           default 0                 null,
    split_budget_allocation           varchar(25)       default ''                not null,
    marketing_budget                  decimal(12)       default 0                 null,
    merchandise_budget                decimal(12)       default 0                 null,
    qty_x_discount                    int                                         null comment 'Maximum Quantity that eligible for discount',
    discount_step                     tinyint unsigned                            null comment 'Discount Qty Step Items X',
    discount_step_max                 int                                         null comment 'Maximum Qty Step items X',
    discount_item_sku                 text                                        null comment 'items Y ( Applied for action buy X get Y )',
    discount_item_qty                 tinyint                                     null comment 'Quantity items Y ( Applied for action buy X get Y )
How many items Y getting discount in single condition',
    discount_item_qty_each            tinyint                                     null comment 'Quantity each items Y ( Applied for action buy X get Y and Type Y is selected )
',
    discount_item_type                varchar(30)                                 null comment 'Type Items Y
- selected
- auto',
    associate_rule_id                 int                                         null,
    voucher_expired                   tinyint           default 0                 not null,
    voucher_generated                 tinyint           default 0                 null comment '1 => automatic
0 => manual',
    max_redemption                    decimal(11, 2)                              null,
    max_quantity                      tinyint           default 0                 not null,
    label_action_id                   int unsigned      default '0'               null comment 'mapping with product_label',
    limit_payment_time                tinyint           default 0                 not null,
    limit_used                        int               default 0                 not null,
    limit_used_version                tinyint           default 0                 not null comment 'Version of limit used (0 = old version, 1 = new version)',
    limit_used_option                 varchar(50)                                 null comment 'Option selected (lifetime | unlimited | daily | weekly | monthly | custom)',
    limit_used_from_date              smallint                                    null comment 'The initial date the promo can be used',
    limit_used_to_date                smallint                                    null comment 'The end date the promo can be used',
    email_template_id                 int               default 0                 not null,
    split_amount                      decimal(11)       default 0                 null,
    split_combine                     tinyint           default 0                 null,
    shop_reminder_id                  varchar(100)      default ''                null,
    email_voucher_created             int               default 0                 null comment 'days',
    template_id_email_voucher_created int               default 0                 null,
    email_voucher_expired             int               default 0                 null comment 'days',
    template_id_email_voucher_expired int               default 0                 null,
    pushnotif_voucher_created         int               default 0                 null,
    pushnotif_voucher_expired         int               default 0                 null,
    code_length                       int                                         null,
    code_format                       varchar(45)                                 null,
    code_prefix                       varchar(45)                                 null,
    code_suffix                       varchar(45)                                 null,
    promo_type                        varchar(45)                                 null,
    company_code                      varchar(45)       default 'ODI'             null,
    status                            smallint          default 10                not null comment 'Is Active',
    created_at                        datetime                                    null,
    updated_at                        datetime          default CURRENT_TIMESTAMP null on update CURRENT_TIMESTAMP,
    tnc                               longtext                                    not null,
    tnc_archived                      longtext                                    null,
    is_auto_tnc                       tinyint           default 0                 not null,
    publish_description               varchar(255)      default ''                not null,
    display_description               varchar(125)      default ''                not null,
    budget_owner                      varchar(55)                                 null comment 'Value: Refund, Ops, Redeem, Sell, Chatime, HCI, AHI, TGI, Ataru, Krisbow, Selma, GSP, Pendopo, KLV, Marketing ODI',
    device_to_publish                 varchar(155)                                null comment 'Value: ruparupa-website, ruparupa-app, informa-app, ace-app, selma-app',
    voucher_title                     varchar(24)                                 null,
    benefit                           varchar(255)                                null,
    is_auto_benefit                   tinyint           default 0                 not null,
    logo_name                         varchar(24)                                 null,
    cdn_link                          longtext                                    null,
    banner_link                       varchar(10000)                              null,
    is_publish                        tinyint           default 0                 null,
    is_voucher_segmented              tinyint           default 0                 null,
    from_time                         varchar(5)                                  null comment 'Rule start of hour usability',
    to_time                           varchar(5)                                  null comment 'Rule end of hour usability',
    is_sku_populated                  tinyint           default 0                 null,
    is_sku_processed                  int                                         null,
    user_id                           int unsigned                                null,
    promo_sap_id                      varchar(100)                                null comment 'sync promo pos referral to know which promo_sap_id synchronize for the salesrule',
    naomi_id                          varchar(255)                                null,
    promo_pos_rule_type               varchar(255)                                null comment 'sync promo pos rule type to determine generated rule type came from which promo pos rule',
    pwp_data                          text                                        null,
    pwp_maximum_item                  int               default 0                 null,
    pwp_multiplier                    tinyint           default 0                 null comment '0=false, 10=true',
    pwp_same_store                    tinyint                                     null comment '0=false, 10=true',
    pwp_multiplier_item               tinyint                                     null comment '0=false, 10=true',
    pwp_multiplier_qty                tinyint                                     null comment '0=false, 10=true',
    pwp_device_to_publish             varchar(155)                                null,
    information_message               varchar(255)                                null,
    tags                              text                                        null,
    label_value                       varchar(255)                                null,
    label_company_code                varchar(45)                                 null,
    label_priority                    int               default 0                 null,
    label_custom                      tinyint                                     null,
    claimable                         int               default 0                 null,
    coin_amount                       decimal(12)       default 0                 null,
    reward_id                         varchar(50)                                 null,
    limit_max_qty_global              int               default 0                 not null,
    limit_max_qty_per_customer        int               default 0                 not null,
    global_can_combine_tags           text                                        null,
    global_can_combine_rule_id        text                                        null,
    is_tiered                         tinyint           default 0                 not null,
    tiered_rules                      varchar(2000)                               null,
    whitelist_order                   tinyint           default 0                 null
)
    comment 'Salesrule' engine = InnoDB
                        charset = utf8mb3;

