create table salesrule_voucher
(
    voucher_id      int unsigned auto_increment
        primary key,
    rule_id         int unsigned                               null,
    voucher_code    varchar(255)                               not null,
    times_used      int unsigned   default '0'                 null comment '1 voucher SUDAH dipakai berapa kali',
    limit_used      int            default 1                   null comment 'Batasan 1  voucher bisa di pakai X kali',
    voucher_amount  decimal(10, 2)                             null,
    percentage      decimal(10, 2) default 0.00                null,
    max_redemption  decimal(10, 2)                             null,
    final_amount    decimal(10, 2) default 0.00                not null,
    expiration_date datetime                                   null,
    customer_id     int            default 0                   null,
    total_stamp     int            default 0                   null,
    company_code    varchar(45)    default 'ODI'               not null,
    created_at      datetime                                   null,
    updated_at      datetime       default CURRENT_TIMESTAMP   not null on update CURRENT_TIMESTAMP,
    created_by      int            default 0                   null,
    status          tinyint        default 10                  null comment '0 => inactive
10 => active
15 => voucher sudah diassign ke cust
6 => dlm proses pencairan dana (voucher refund)
7 => voucher refund tidak tampil ke cust, refund direct rekening
8 => voucher dihide karena refund sedang diproses untuk reversal',
    note            text                                       null,
    type            smallint       default 0                   null comment '-5. Cust kirim ke cust lain (ref : ace_send_voucher )\n1. Registration\n2. Refund\n3. General\n4. Cashback\n5. Redeem\n6. New Retail -> exclude dari user blacklist\r\n7. Digital Stamp\r\n8. Voucher As Cash\r\n9. Internas Sales GP',
    channel         tinyint        default 2                   null comment '1 = OFFLINE, 2 = ONLINE, 3 = OMNICHANNEL',
    voucher_source  varchar(25)    default 'general-marketing' null,
    redemption_id   int            default 0                   not null,
    constraint voucher_code_UNIQUE
        unique (voucher_code),
    constraint voucher_id_UNIQUE
        unique (voucher_id)
)
    engine = InnoDB
    charset = utf8mb3;

create table customer_point_redeem
(
    customer_point_redeem_id int auto_increment
        primary key,
    customer_id              int                                      not null,
    sales_rule_voucher_id    int unsigned                             null,
    point_redeemed           int                                      null,
    company_code             enum ('ODI', 'AHI', 'HCI', 'TGI', 'SLM') not null,
    created_at               timestamp default CURRENT_TIMESTAMP      null,
    constraint fk_customer_point_redeems_1
        foreign key (customer_id) references customer (customer_id)
            on update cascade,
    constraint fk_customer_point_redeems_2
        foreign key (sales_rule_voucher_id) references salesrule_voucher (voucher_id)
            on update cascade
)
    engine = InnoDB;

