create table supplier_address
(
    supplier_address_id    int auto_increment
        primary key,
    supplier_id            int                not null,
    province_id            int                null,
    province_code          varchar(30)        null,
    city_id                int                null,
    kecamatan_id           int                null,
    kecamatan_code         varchar(100)       null,
    kelurahan_id           int                null,
    supplier_address_type  tinyint default 2  null comment '1 => Customer Service
2 => Warehouse
3 => Head Office',
    address_point          varchar(200)       null,
    address                text               null,
    phone                  varchar(45)        null,
    fax                    varchar(45)        null,
    is_default             tinyint default 0  null,
    status                 tinyint default 10 null comment '-1 => delete
0 => disabled
10 => enabled',
    geolocation            varchar(100)       null,
    instant_courier_status tinyint default 0  null,
    created_at             datetime           null,
    updated_at             datetime           null,
    constraint fk_supplier_address_master_city
        foreign key (city_id) references master_city (city_id),
    constraint fk_supplier_address_master_kecamatan
        foreign key (kecamatan_code) references master_kecamatan (kecamatan_code),
    constraint fk_supplier_address_master_province
        foreign key (province_code) references master_province (province_code)
)
    engine = InnoDB
    charset = utf8mb3;

create index fk_supplier_address_master_city_idx
    on supplier_address (city_id);

create index fk_supplier_address_master_kecamatan_idx
    on supplier_address (province_code);

create index fk_supplier_address_master_kecamatan_idx1
    on supplier_address (kecamatan_code);

create index fk_supplier_address_supplier1_idx
    on supplier_address (supplier_id);

