create table tiktok_access_tokens
(
    tiktok_access_token_id  bigint auto_increment
        primary key,
    shop_id                 int                                            not null,
    access_token            varchar(255)                                   not null,
    access_token_expire_in  bigint                                         not null,
    refresh_token           varchar(255)                                   not null,
    refresh_token_expire_in bigint                                         not null,
    open_id                 varchar(255)                   default ''      not null,
    seller_name             varchar(100)                                   not null,
    seller_base_region      varchar(45)                                    not null,
    user_type               tinyint(1)                                     not null,
    cipher                  varchar(255)                   default ''      not null,
    code                    varchar(45)                    default ''      not null,
    seller_type             enum ('LOCAL', 'CROSS_BORDER') default 'LOCAL' not null,
    constraint shop_id
        unique (shop_id)
)
    engine = InnoDB;

create table tiktok_cancellations
(
    id                    int auto_increment
        primary key,
    sales_order_vendor_id int                                 not null,
    shop_id               int                                 not null,
    cancel_id             varchar(32)                         not null,
    cancel_status         varchar(50)                         not null,
    cancellations_role    varchar(32)                         not null,
    order_id              varchar(32)                         not null,
    created_at            timestamp default CURRENT_TIMESTAMP null,
    updated_at            timestamp default CURRENT_TIMESTAMP null on update CURRENT_TIMESTAMP,
    constraint tiktok_cancellations_unique_cancel_id
        unique (cancel_id),
    constraint tiktok_cancellations_ibfk_1
        foreign key (sales_order_vendor_id) references sales_order_vendor (sales_order_vendor_id)
)
    engine = InnoDB;

