create table transaction_wholesale
(
    id                       bigint auto_increment
        primary key,
    created_by_admin_user_id int unsigned                        not null,
    transaction_no           varchar(32)                         not null,
    created_at               timestamp default CURRENT_TIMESTAMP not null,
    updated_at               timestamp default CURRENT_TIMESTAMP not null on update CURRENT_TIMESTAMP,
    constraint transaction_no
        unique (transaction_no),
    constraint transaction_wholesale_ibfk_1
        foreign key (created_by_admin_user_id) references admin_user (admin_user_id)
)
    engine = InnoDB;

create index created_by_admin_user_id
    on transaction_wholesale (created_by_admin_user_id);

create table transaction_wholesale_request
(
    id                          bigint auto_increment
        primary key,
    transaction_wholesale_id    bigint                                   not null,
    customer_b2c_id             int                                      null,
    request_no                  varchar(32)                              not null,
    bu                          varchar(16)                              not null,
    status                      varchar(16)                              not null,
    subtotal                    decimal(16, 2)                           not null,
    discount_amount             decimal(16, 2)                           not null,
    marketing_discount_amount   decimal(16, 2) default 0.00              not null,
    marketing_gift_cards_amount decimal(16, 2) default 0.00              not null,
    approved_at                 timestamp                                null,
    rejected_at                 timestamp                                null,
    approved_by_admin_user_id   int unsigned                             null,
    rejected_by_admin_user_id   int unsigned                             null,
    created_at                  timestamp      default CURRENT_TIMESTAMP not null,
    updated_at                  timestamp      default CURRENT_TIMESTAMP not null on update CURRENT_TIMESTAMP,
    constraint request_no
        unique (request_no),
    constraint transaction_wholesale_request_ibfk_1
        foreign key (transaction_wholesale_id) references transaction_wholesale (id),
    constraint transaction_wholesale_request_ibfk_2
        foreign key (customer_b2c_id) references customer (customer_id),
    constraint transaction_wholesale_request_ibfk_3
        foreign key (approved_by_admin_user_id) references admin_user (admin_user_id),
    constraint transaction_wholesale_request_ibfk_4
        foreign key (rejected_by_admin_user_id) references admin_user (admin_user_id)
)
    engine = InnoDB;

create index approved_by_admin_user_id
    on transaction_wholesale_request (approved_by_admin_user_id);

create index customer_b2c_id
    on transaction_wholesale_request (customer_b2c_id);

create index rejected_by_admin_user_id
    on transaction_wholesale_request (rejected_by_admin_user_id);

create index transaction_wholesale_id
    on transaction_wholesale_request (transaction_wholesale_id);

create table transaction_wholesale_request_item
(
    id                                      bigint auto_increment
        primary key,
    transaction_wholesale_request_id        bigint                                   not null,
    sales_quotation_wholesale_id            bigint                                   not null,
    sales_quotation_wholesale_item_id       bigint                                   null,
    sku                                     varchar(32)                              not null,
    name                                    varchar(256)                             not null,
    bu                                      varchar(16)                              not null,
    image_url                               text                                     not null,
    department_name                         varchar(256)                             not null,
    qty                                     int                                      not null,
    normal_price                            decimal(16, 2)                           not null,
    special_price                           decimal(16, 2)                           not null,
    zone_id                                 int            default 1                 not null,
    handling_fee_adjust                     decimal(16, 2)                           not null,
    discount_type                           enum ('fix', 'percentage')               null,
    discount_amount                         decimal(16, 2) default 0.00              not null,
    marketing_discount_amount               decimal(16, 2) default 0.00              not null,
    marketing_gift_cards_amount             decimal(16, 2) default 0.00              not null,
    marketing_total_discount_prorate_diff   decimal(16, 2) default 0.00              not null,
    marketing_total_gift_cards_prorate_diff decimal(16, 2) default 0.00              not null,
    created_at                              timestamp      default CURRENT_TIMESTAMP not null,
    updated_at                              timestamp      default CURRENT_TIMESTAMP not null on update CURRENT_TIMESTAMP,
    constraint transaction_wholesale_request_item_ibfk_1
        foreign key (transaction_wholesale_request_id) references transaction_wholesale_request (id),
    constraint transaction_wholesale_request_item_ibfk_2
        foreign key (sales_quotation_wholesale_id) references sales_quotation_wholesale (id),
    constraint transaction_wholesale_request_item_ibfk_3
        foreign key (sales_quotation_wholesale_item_id) references sales_quotation_wholesale_item (id)
)
    engine = InnoDB;

create index sales_quotation_wholesale_id
    on transaction_wholesale_request_item (sales_quotation_wholesale_id);

create index sales_quotation_wholesale_item_id
    on transaction_wholesale_request_item (sales_quotation_wholesale_item_id);

create index transaction_wholesale_request_id
    on transaction_wholesale_request_item (transaction_wholesale_request_id);

