(
    voucher_deals_id         int unsigned auto_increment
        primary key,
    identifier               varchar(255)                             not null,
    rule_id                  int unsigned                             not null,
    status                   tinyint        default 0                 not null comment '10 => active
0 => inactive
-1 => deleted',
    platform                 varchar(255)   default ''                not null comment 'apps,desktop,mobile',
    discount_type            varchar(45)    default 'fix'             not null comment 'fix,percent,final_amount',
    voucher_amount           int                                      not null,
