    user_type                tinyint        default 0                 not null comment '1 => member only
0 => all user',
    online_status            tinyint                                  null,
    offline_status           tinyint                                  null,
    online_quota             int unsigned                             null,
    offline_quota            int unsigned                             null,
    company_code             varchar(45)    default 'ODI'             not null,
    title                    varchar(255)                             not null,
    description              text                                     null,
    tnc                      text                                     null,
    banner_image_small_url   varchar(255)                             not null,
    banner_image_small_title varchar(255)                             not null,
    banner_image_large_url   varchar(255)                             not null,
    banner_image_large_title varchar(255)                             not null,
    voucher_code_length      int                                      null,
    voucher_code_prefix      varchar(45)                              null,
    priority_list            tinyint        default 1                 not null,
    page_url                 varchar(255)                             null,
    start_at                 datetime                                 null,
    expired_at               datetime                                 null,
    created_at               datetime       default CURRENT_TIMESTAMP null,
    updated_at               datetime                                 null on update CURRENT_TIMESTAMP,
    created_by               int                                      not null,
    updated_by               int                                      not null,
    constraint identifier_UNIQUE
        unique (identifier),
    constraint rule_id
        unique (rule_id),
    constraint voucher_deals_id_UNIQUE
        unique (voucher_deals_id)
)
    engine = InnoDB;

